style.css:
@-moz-document domain("csdn.net") {
/* ============================================================
     CSDN Dark
     CSDN (csdn.net + blog.csdn.net + so./ask./bbs./download.) is
     built on hardcoded colors, not a design-token system, so the
     theme works by (1) painting the page base + content cards
     dark, (2) neutralizing the many white containers, and (3)
     fully recoloring code blocks + the highlight.js syntax
     palette, which is the core surface on a developer site.
     GitHub-dark-ish palette throughout.
     ============================================================ */

  :root {
    color-scheme: dark;
    --csdn-base: #14181d;
    --csdn-elev: #1c2128;
    --csdn-elev2: #21262d;
    --csdn-chrome: #0d1117;
    --csdn-border: #2d333b;
    --csdn-border-soft: #262c33;
    --csdn-text: #e6edf3;
    --csdn-text-2: #c4cdd6;
    --csdn-muted: #8b949e;
    --csdn-link: #5fb0e6;
    --csdn-link-hover: #9bd4ff;
    --csdn-code-bg: #161b22;
    --csdn-red: #f0795c;
  }

  /* ---------- Base ---------- */
  html,
  body {
    background-color: var(--csdn-base) !important;
    color: var(--csdn-text-2) !important;
  }
  /* blog articles can carry an author-chosen "skin" that paints a light
     full-page raster (e.g. skin-1024 bg.gif) as a body background-IMAGE —
     drop it so the dark base shows through (bg-color audit misses url() bgs) */
  body.nodata {
    background-image: none !important;
  }

  /* Soften every light border into a subtle dark one */
  * {
    border-color: var(--csdn-border-soft) !important;
  }

  /* ---------- Broad white-surface neutralizer ----------
     Most CSDN section wrappers carry a hardcoded white bg.
     Flatten them to transparent so the dark base shows through,
     then re-establish solid dark on the real cards + floating
     surfaces below (so nothing bleeds through). */
  body div[class],
  body section[class],
  body aside[class],
  body main,
  body article {
    background-color: transparent !important;
  }

  /* ---------- Page wrappers / layout ---------- */
  #app,
  .layout-container,
  .home_wrap_box,
  #mainBox,
  main,
  .container,
  .blog_container,
  .blog_container_aside,
  .recommend-box,
  .recommend-right,
  .article_content,
  #content_views,
  .toc-box {
    background-color: transparent !important;
    color: var(--csdn-text-2) !important;
  }
  /* article TOC ("目录") active item ships a near-white highlight
     (rgb 240,240,245) — recolor to a dark surface + red accent text,
     scoped to the toc-box so it can't catch unrelated .active items */
  .toc-box li.active,
  .toc-box li.active a {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-red) !important;
  }

  /* ---------- Elevated cards / panels ---------- */
  .blog-content-box,
  #asideProfile,
  .aside-box,
  .recommend-item-box,
  .recommend-card,
  .first-recommend-box,
  .recommend-ad-box,
  .blog_extension,
  .article-info-box,
  .comment-box,
  .comment-list-box,
  .more-toolbox-new,
  .calendar,
  .calendar-content-item,
  .card,
  .Community,
  .feed-card,
  .blink-card,
  .floor-item,
  .item,
  .nav-second,
  .kind_list,
  .left-box,
  .right-box,
  .container-fluid,
  .csdn-tracking-statistics,
  .csdn-toolbar-plugin,
  .layout-sidebar-aside,
  .csdn-common-logo-box {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }

  /* Slightly lighter blue promo tiles -> elevated */
  .project-item,
  a.project-item {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }
  /* white pill button inside promo tiles */
  .project-item p.btn,
  .project-bottom .btn,
  .project-bottom p.btn {
    background-color: var(--csdn-link) !important;
    color: #0d1117 !important;
    border-color: var(--csdn-link) !important;
  }

  /* In-article reference / link cards + recommend rows + tables */
  .link-card-box,
  .link-card,
  span.link-card-box,
  .recommend-box .recommend-item-box,
  .blog-content-box table,
  .blog-content-box tr,
  .recommend-card-box,
  .more-toolbox-new .toolbox-list,
  .csdn-edu-comment,
  .insert-card,
  .csdn-blog-text-card {
    background-color: var(--csdn-elev) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  .link-card-box .link-title,
  .link-card-box .link-link,
  .recommend-item-box .tit,
  .recommend-item-box .dec,
  .recommend-item-box .blog-text {
    color: var(--csdn-text-2) !important;
  }

  /* Paid-column promo card embedded in articles */
  #blogColumnPayAdvert,
  .column-group,
  .column-group-item,
  .column-group-item-one,
  .column-info,
  .profile-intro-name-years,
  .profile-intro-name-boxFooter {
    background-color: var(--csdn-elev) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  #blogColumnPayAdvert .tit,
  #blogColumnPayAdvert .title,
  .column-group-item .tit {
    color: var(--csdn-text) !important;
  }
  #blogColumnPayAdvert .dec,
  .column-group-item .dec,
  .profile-intro-name-years {
    color: var(--csdn-muted) !important;
  }

  /* "原创 / 转载" article-type badge — tone the pink chip for dark */
  .article-type-text,
  .article-type-text.original,
  .article-type-text.fovorite,
  .article-bar-top .article-type {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
  }
  /* the profile article-list "原创" badge is a separate class (.article-type-yc — a red
     rgb(227,62,51) label on a rgba(227,62,51,.1) red-tint chip) the rule above never
     reached: the blanket div text rule greyed the label and the broad neutralizer
     stripped the tint, so 原创 read as plain metadata grey, indistinguishable from the
     阅读/点赞 counts beside it. Restore a dark-tuned red badge; the (0,2,0) selector
     out-specifies the `body div[class]` (0,1,1) neutralizer for the background. */
  .article-type.article-type-yc {
    background-color: rgba(240, 121, 92, 0.14) !important;
    color: var(--csdn-red) !important;
  }
  /* the profile article-list "置顶" (pinned) marker is yet another article-type
     variant (.article-type-zd) the yc rule never reached: the site paints it a
     distinct blue rgb(64,158,255) to set pinned posts apart from the red 原创 pill,
     but the blanket div text rule greyed it, so 置顶 read as plain metadata next to
     the 发布博客/date. Restore a dark-tuned blue; (0,2,0) beats the blanket text rule. */
  .article-type.article-type-zd {
    color: var(--csdn-link) !important;
  }

  /* ---------- Fixed / floating chrome (must stay opaque) ---------- */
  #csdn-toolbar,
  #toolbarBox,
  .toolbar-container,
  .csdn-toolbar,
  .home_box_nav,
  .blog_nav,
  .toolbar-container-sidebar-www,
  .csdn-side-toolbar,
  .more-toolbox-new,
  .pop-box,
  .toolbar-search-container,
  .dropdown-menu,
  .el-dropdown-menu,
  .toolbar-menu,
  .nav-second-floor,
  .toolbar-btn-loginfun {
    background-color: var(--csdn-chrome) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text) !important;
  }

  /* keep the fixed header reliably solid */
  #csdn-toolbar {
    background-color: var(--csdn-chrome) !important;
  }
  /* The www.csdn.net category-chip bar (.home_box_nav) is position:fixed and
     natively opaque white, but it is a <div class>, so the broad neutralizer
     (body div[class], higher specificity) flattens it to transparent — the feed
     then scrolls straight through the gaps between the chips. Re-seat it
     opaque on the page base. */
  body div.home_box_nav {
    background-color: var(--csdn-base) !important;
  }

  /* Toolbar search autocomplete flyout: the .toolbar-search-drop-menu
     (associate-word) panel + its .drop-menu-list are flattened to
     transparent by the broad neutralizer, so the open suggestion list
     bleeds the page content (carousel + feed) through behind its rows.
     Re-establish a solid dark surface + a hover state. */
  body div.toolbar-search-drop-menu,
  body div.associate-word-drop-menu,
  .toolbar-search-drop-menu .drop-menu-list,
  .drop-menu-list,
  .drop-menu-list li {
    background-color: var(--csdn-chrome) !important;
    color: var(--csdn-text-2) !important;
  }
  .drop-menu-list li:hover,
  .drop-menu-list li.active {
    background-color: var(--csdn-elev2) !important;
  }
  /* The "创作" (write) toolbar flyout is the .csdn-toolbar-plugin panel; it is
     listed in the elevated-cards block but the broad neutralizer
     (body div[class], higher specificity) flattens it to transparent, so the
     open flyout header bleeds the nav chips + page through. Boost specificity
     to re-seat its opaque chrome surface. */
  body div.csdn-toolbar-plugin,
  body div.csdn-toolbar-plugin-container {
    background-color: var(--csdn-chrome) !important;
  }

  /* Toolbar dropdown menus + their items */
  .toolbar-menu-list,
  .toolbar-menu-list li {
    background-color: var(--csdn-chrome) !important;
    color: var(--csdn-text-2) !important;
  }
  .toolbar-menu-list li:hover {
    background-color: var(--csdn-elev2) !important;
  }

  /* Home category-chip carousel (.menus-view). Each chip is a <p> inside
     li.menus-item: natively a light #f2f2f2 pill, and the SELECTED chip is a
     BLACK pill with white text. Painting every chip (and both states) the same
     dark chrome erased the selection entirely — the active category read
     identically to the eleven inactive ones. Mirror the native inversion:
     recessed pill for inactive, bright pill with dark text for the selected. */
  .menus-view,
  .menus-view .menus-item {
    background-color: transparent !important;
  }
  /* category chips are <p>; the sponsored "tag-nav" chips are <a> — both ship
     the same light #f2f2f2 pill, so both need the recessed dark pill */
  .menus-view .menus-item p,
  .menus-view .menus-item a {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }
  .menus-view .menus-item p:hover,
  .menus-view .menus-item a:hover {
    background-color: #30363d !important;
  }
  /* declared after :hover on purpose — equal specificity, so the selected chip
     keeps its bright pill while hovered (and no :not() reaches the .org mirror) */
  .menus-view .menus-item p.active {
    background-color: var(--csdn-text) !important;
    color: var(--csdn-chrome) !important;
  }
  /* blog.csdn.net/nav/<category> ships its OWN chip row inside .home_box_nav
     (.home_box_nav_list > a — 推荐 / 付费专栏 / VIP文章): the inactive chips are a
     light #f2f2f2 pill and the selected one a BLACK pill, exactly like the home
     carousel, but they are <a> under a different container so the .menus-view
     rules never reached them. Our `.home_box_nav a` rule lifted their labels to
     white, leaving the two inactive chips white-on-white (81×32 — under the audit
     big() floor). Mirror the home chip inversion; div-prefixed so it out-specifies
     the later `.home_box_nav a` colour rule. */
  div.home_box_nav_list a {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }
  div.home_box_nav_list a:hover {
    background-color: #30363d !important;
  }
  div.home_box_nav_list a.active {
    background-color: var(--csdn-text) !important;
    color: var(--csdn-chrome) !important;
  }

  /* toolbar top-nav dropdown items (.toolbar-subMenu — e.g. "更多" holding
     会议/学习) paint a near-white rgb(240,240,245) highlight on the trigger
     box when hovered/open (audit-blind: :hover state + 67px wide, under the
     big() threshold). Repaint the hover box + its flyout to dark chrome. */
  .toolbar-subMenu-box:hover,
  .toolbar-subMenu:hover .toolbar-subMenu-box,
  .toolbar-subMenu-list,
  .toolbar-subMenu-list li:hover {
    background-color: var(--csdn-chrome) !important;
  }

  /* Article action-bar "觉得还不错？" nudge bubble: the .tool-active-list
     speech bubble is drawn entirely by white ::before (body) + ::after
     (arrow) pseudo-elements (audit-blind — pseudos, and the box is only
     32px tall). Repaint both dark so its light label is legible. */
  .tool-active-list::before,
  .tool-active-list::after {
    background-color: var(--csdn-elev2) !important;
  }
  .tool-active-list .text,
  .tool-active-list .text * {
    color: var(--csdn-text-2) !important;
  }

  /* ---------- Right-edge floating side toolbar (every page) ----------
     Each .option-box circle (手机看 QR / 客服 / 返回顶部 / CSDN GO) ships a
     literal white 44px disc: it is an <a>, so the div/section neutralizer
     never touches it, and at 44px it sits under the audit big() threshold.
     Darken the disc and invert the monochrome near-black raster glyphs that
     were drawn for a white background. The colored CSDN-GO badge
     (Group.png) is deliberately NOT inverted so it keeps its brand colors. */
  .csdn-side-toolbar a.option-box,
  a.option-box {
    background-color: var(--csdn-elev2) !important;
    border-color: var(--csdn-border) !important;
  }
  /* the label layer that covers each disc (hover caption, and the always-on
     "GO" caption on the CSDN-GO badge) is its own white <span> */
  a.option-box .show-txt {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
    -webkit-text-fill-color: var(--csdn-text-2) !important;
  }
  a.option-box > img[src*="/mobile"],
  a.option-box > img[src*="/customer"],
  a.option-box > img[src*="/totop"],
  a.option-box > img[src*="/qr."],
  a.option-box > img[src*="/fanhuidingbu"] {
    filter: invert(1) brightness(0.85) !important;
  }
  /* the 手机看 hover flyout (.app-qr-box) is a <div>, so the neutralizer
     flattens it to transparent and the page scrolls through behind the QR
     panel — re-establish a solid chrome surface (floating-surface bleed) */
  body div.app-qr-box,
  body div.app-qr-box .bg-box {
    background-color: var(--csdn-chrome) !important;
    border-color: var(--csdn-border) !important;
  }
  /* the flyout's three tabs (下载APP / 公众号 / 视频号) stack their .tab-content
     panels absolutely on top of each other; natively each is opaque WHITE, so the
     selected one (z-index 1) hides the other two. The neutralizer flattened all
     three to transparent, so the QR codes and captions of all three tabs rendered
     superimposed. Re-seat them opaque. */
  body div.app-qr-box .tab-content {
    background-color: var(--csdn-chrome) !important;
  }
  body div.app-qr-box .tab-item {
    color: var(--csdn-text-2) !important;
  }

  /* ---------- Blog-article floating bars (must stay opaque) ----------
     Both are <div>s flattened by the broad neutralizer, so the article text
     scrolls straight through them: the bottom action bar (.left-toolbox —
     赞/收藏/评论/分享 + the author follow strip) and the guest "登录后您可以
     享受以下权益" tip card (.passport-login-tip-container, z-index 9999). */
  body div.left-toolbox,
  body div.passport-login-tip-container {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
  }

  /* article aside 归档 (archive) month tiles: the month label ships a light
     rgb(237,240,243) box and the post-count a rgb(246,248,250) one — 56×22,
     under the audit big() floor, so both go light-on-light once our theme
     lifts their labels. */
  .archive-box .archive-item span.time,
  .archive-box .archive-item span.count {
    background-color: var(--csdn-elev2) !important;
    border-color: var(--csdn-border) !important;
  }
  .archive-box .archive-item span.count {
    color: var(--csdn-text-2) !important;
  }

  /* profile aside "展开" expand buttons (.aside-common-box-bottom-btn) ship a
     light-grey rgb(245,246,247) 40×16 pill — a <button>, audit-blind twice.
     Its chevron is an <i class="el-icon-arrow-down"> whose own #555666 survives
     the button's color (a ::before glyph, 2.11:1 on the dark pill). */
  .aside-common-box-bottom-btn,
  .aside-common-box-bottom button {
    background-color: var(--csdn-elev2) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-muted) !important;
  }
  .aside-common-box-bottom-btn i,
  .aside-common-box-bottom button i {
    color: var(--csdn-muted) !important;
  }
  /* Element-UI icon-FONT glyphs are drawn by an <i>'s ::before, so they keep the
     site's dark #555666 (our text rules never reach a pseudo). The decorative
     "更多 ›" chevrons (so.csdn 相关课程 header, bbs quick-links) measured 2.5:1 on the
     dark base — under even the 3:1 non-text floor. Lift only the arrow/search
     glyphs: the semantic ones (el-icon-plus in a brand CTA, close crosses) keep
     their own colour. */
  i.el-icon-arrow-right,
  i.el-icon-arrow-left,
  i.el-icon-arrow-down,
  i.el-icon-arrow-up,
  i.el-icon-search {
    color: var(--csdn-muted) !important;
  }

  /* Side copyright/contact footer popover */
  .csdnside-copyright-footer-contact,
  .csdnside-copyright-footer-contact .work-time-btn,
  .csdnside-copyright-footer-contact .link {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }

  /* ---------- Headings + body text ---------- */
  h1, h2, h3, h4, h5, h6,
  .title-article,
  .article-title,
  .blog-title,
  .text-title,
  .title,
  .name,
  .user-name,
  .nick-name,
  .username,
  b, strong {
    color: var(--csdn-text) !important;
  }

  /* NOTE: no `#content_views span` here. An ID-scoped span rule is (1,0,2) and
     therefore out-specifies EVERY syntax-token class (.hljs-keyword (0,1,0),
     .token.keyword (0,2,0)) — it silently repainted both palettes body-grey, so
     article code blocks rendered with no highlighting at all. The plain `span`
     rule below already covers article prose. */
  p, span, li, td, th, dd, dt, label, div,
  .text,
  .summary,
  .desc,
  .blog-text,
  .markdown_views,
  #content_views,
  #content_views p,
  #content_views li,
  .comment-content {
    color: var(--csdn-text-2) !important;
  }

  /* Muted metadata (read counts, dates, tags) */
  .read-count,
  .time,
  .date,
  .read-num,
  .num,
  .blog-tags-box span,
  .tag,
  .meta,
  .info,
  .recommend-item-box .desc,
  .article-info-box .time,
  .comment-time,
  .text-gray,
  .gray {
    color: var(--csdn-muted) !important;
  }
  /* search-result download-size metadata ships a hardcoded dark grey
     (#555666) via a higher-specificity site rule — lift to muted, and set
     the fill too in case the site drives it through -webkit-text-fill-color */
  body .so-items-bottom .btm-lt .download-size,
  body .so-result .download-size,
  body .download-size {
    color: var(--csdn-muted) !important;
    -webkit-text-fill-color: var(--csdn-muted) !important;
  }

  /* ---------- Links ---------- */
  a,
  a:visited,
  #content_views a {
    color: var(--csdn-link) !important;
  }
  a:hover,
  #content_views a:hover {
    color: var(--csdn-link-hover) !important;
  }
  /* keep nav/card links that should look like text */
  .toolbar-container a,
  .home_box_nav a,
  .feed-card a.title,
  .blog-content-box a.title {
    color: var(--csdn-text) !important;
  }
  .toolbar-container a:hover,
  .home_box_nav a:hover {
    color: var(--csdn-link-hover) !important;
  }
  /* the toolbar 会员·新人礼包 promo link carries an inline color:#FC5531 — our
     blanket `a` / `.toolbar-container a` rules erase it (inline colours lose to
     !important), so the one deliberately-red toolbar item shipped plain white.
     Restore a dark-tuned brand red. The download.csdn.net (文库) toolbar carries a
     second such promo, "VIP省70元起" (a.toolbar-btn.activity-text — native coral
     rgb(255,103,80)), which the same blanket rules flattened to white while the
     会员·新人礼包 beside it kept its red: both are deliberate upsell accents, so
     tone activity-text to the same brand red. (0,2,0) beats `.toolbar-container a`. */
  .toolbar-btn-vip a,
  .toolbar-btn-vip a:hover,
  .toolbar-btn.activity-text,
  .toolbar-btn.activity-text:hover {
    color: var(--csdn-red) !important;
  }
  /* home feed card summaries are <a class="article-desc">, natively a muted
     #999 — the blanket `a` rule painted them link-blue, so every card body read
     as a hyperlink. Put them back to metadata grey. */
  a.article-desc {
    color: var(--csdn-muted) !important;
  }
  a.article-desc:hover {
    color: var(--csdn-text-2) !important;
  }
  /* in-article promoted keyword (span.new-words-blog) ships an inline
     color:#FC5531 that our `span` rule flattens to body grey — the hot-word
     stops looking clickable */
  span.new-words-blog {
    color: var(--csdn-red) !important;
  }

  /* ---------- Inputs / forms / search ---------- */
  input,
  textarea,
  select,
  .toolbar-search,
  .toolbar-search-input,
  .comment-edit-box,
  .comment-operate-box {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text) !important;
    border-color: var(--csdn-border) !important;
  }
  input::placeholder,
  textarea::placeholder {
    color: var(--csdn-muted) !important;
    opacity: 1 !important;
  }
  input::-webkit-input-placeholder,
  textarea::-webkit-input-placeholder {
    color: var(--csdn-muted) !important;
  }

  /* ---------- Buttons ---------- */
  .btn,
  button,
  .button,
  .btn-comment,
  .submit-btn,
  .more-btn {
    border-color: var(--csdn-border) !important;
  }

  /* ============================================================
     CODE BLOCKS — the core developer surface.
     CSDN lets authors pick a "skin" (atom-one-light/-dark,
     github, etc.) so token colors vary wildly and the light
     skins are unreadable on dark. Force every code block to the
     dark base + apply one consistent, legible syntax palette,
     overriding whatever skin class is on the wrapper.
     ============================================================ */
  pre,
  pre.hljs,
  pre code,
  pre code.hljs,
  .hljs,
  .htmledit_views pre,
  .htmledit_views code,
  code.hljs,
  #content_views pre,
  .markdown_views pre {
    background: var(--csdn-code-bg) !important;
    background-color: var(--csdn-code-bg) !important;
    color: #c9d1d9 !important;
    border-color: var(--csdn-border) !important;
  }

  /* CSDN's interactive code widgets (the "运行项目/登录复制" blocks that show a
     language label like "undefined"/"groovy"/"erlang-repl") drive the <code>
     text through a rule that ALSO sets -webkit-text-fill-color to a dark
     #4f4f4f — which overrides our plain `color` at RENDER time, so plain /
     unhighlighted code lines ship dark-on-dark (audit-blind: text-fill-color).
     Re-assert a readable base color with higher specificity and pin the
     text-fill so it can't override us. */
  .markdown_views pre code,
  .markdown_views pre code.hljs,
  #content_views pre code,
  #content_views pre code.hljs,
  pre.set-code-show code,
  pre.set-code-show code.hljs {
    color: #c9d1d9 !important;
    -webkit-text-fill-color: #c9d1d9 !important;
  }
  /* keep every syntax-token span rendering its OWN palette color — make the
     text-fill follow `color` so the pinned base fill above can't bleed in */
  pre code span,
  .hljs span,
  pre code [class*="hljs-"] {
    -webkit-text-fill-color: currentColor !important;
  }

  /* Inline code inside prose. Written WITHOUT `:not(pre code)` — a complex
     :not() is stripped from .org.css, so userstyles.org only ever received the
     `p code` / `li code` arms and left inline code in tables, headings and
     blockquotes unstyled. Matching every `code` under the article roots and then
     re-asserting the block appearance below is equivalent and survives sanitizing.
     The reset is REQUIRED: `#content_views code` is (1,0,1) and out-ranks the
     block rule's bare `pre code` (0,0,2), so without it a code block's <code>
     would take the inline pill background. */
  #content_views code,
  .markdown_views code,
  #content_views p code,
  #content_views li code,
  p code,
  li code {
    background-color: var(--csdn-elev2) !important;
    color: #e6a98c !important;
    border-color: var(--csdn-border) !important;
  }

  /* …and put code INSIDE a block back to the block appearance. (1,0,2) beats the
     inline rule above; the bare `pre code` arm is later in source order, so it
     also beats the bare `p code` / `li code` arms. */
  #content_views pre code,
  #content_views pre code.hljs,
  .markdown_views pre code,
  .markdown_views pre code.hljs,
  pre code,
  pre code.hljs {
    background-color: var(--csdn-code-bg) !important;
    color: #c9d1d9 !important;
    border-color: var(--csdn-border) !important;
  }

  /* code line numbers — the gutter container (ul.pre-numbering) ships a
     near-white #fafafa bg (it's a <ul>, so the div/section neutralizer misses
     it), leaving the numbers in white cells beside the dark code. Paint the
     gutter to the code base and mute the numbers. */
  ul.pre-numbering,
  .pre-numbering {
    background-color: var(--csdn-code-bg) !important;
    border-color: var(--csdn-border) !important;
  }
  .hljs-ln-numbers,
  .hljs-ln-n,
  .pre-numbering li,
  .line-numbers-rows span {
    color: #6e7681 !important;
    background-color: transparent !important;
  }

  /* code copy / toolbar button */
  pre .hljs-button,
  .hljs-button,
  .code-toolbar,
  .hljs-comment-copy,
  .copy-code-btn {
    color: var(--csdn-muted) !important;
    background-color: transparent !important;
  }
  pre .hljs-button:hover,
  .hljs-button:hover {
    color: var(--csdn-link) !important;
  }

  /* ---- highlight.js syntax palette (GitHub-dark) ----
     CSDN's markdown_views stylesheet ships its own hljs skin as
     `.markdown_views .hljs-keyword { color: #000088 !important }` — (0,2,0) and
     !important, so a bare `.hljs-keyword !important` (0,1,0) LOSES and the whole
     palette silently reverted to the site's light-theme token colours inside
     every article. #content_views IS the .markdown_views element, so an
     ID-prefixed twin of each selector (1,1,0) out-specifies it. The bare
     selectors stay for hljs blocks outside the article body. */
  .hljs-comment,
  .hljs-quote,
  #content_views .hljs-comment,
  #content_views .hljs-quote {
    color: #8b949e !important;
    font-style: italic;
  }
  .hljs-keyword,
  .hljs-selector-tag,
  .hljs-literal,
  .hljs-type,
  .hljs-deletion,
  .hljs-subst,
  #content_views .hljs-keyword,
  #content_views .hljs-selector-tag,
  #content_views .hljs-literal,
  #content_views .hljs-type,
  #content_views .hljs-deletion,
  #content_views .hljs-subst {
    color: #ff7b72 !important;
  }
  .hljs-string,
  .hljs-meta-string,
  .hljs-regexp,
  .hljs-addition,
  #content_views .hljs-string,
  #content_views .hljs-meta-string,
  #content_views .hljs-regexp,
  #content_views .hljs-addition {
    color: #a5d6ff !important;
  }
  .hljs-number,
  .hljs-symbol,
  .hljs-bullet,
  .hljs-link,
  #content_views .hljs-number,
  #content_views .hljs-symbol,
  #content_views .hljs-bullet,
  #content_views .hljs-link {
    color: #79c0ff !important;
  }
  .hljs-title,
  .hljs-function .hljs-title,
  .hljs-section,
  .hljs-name,
  #content_views .hljs-title,
  #content_views .hljs-function .hljs-title,
  #content_views .hljs-section,
  #content_views .hljs-name {
    color: #d2a8ff !important;
  }
  .hljs-attr,
  .hljs-attribute,
  .hljs-variable,
  .hljs-template-variable,
  .hljs-selector-attr,
  .hljs-selector-pseudo,
  .hljs-selector-class,
  .hljs-selector-id,
  #content_views .hljs-attr,
  #content_views .hljs-attribute,
  #content_views .hljs-variable,
  #content_views .hljs-template-variable,
  #content_views .hljs-selector-attr,
  #content_views .hljs-selector-pseudo,
  #content_views .hljs-selector-class,
  #content_views .hljs-selector-id {
    color: #79c0ff !important;
  }
  .hljs-built_in,
  .hljs-builtin-name,
  .hljs-class .hljs-title,
  .hljs-meta,
  #content_views .hljs-built_in,
  #content_views .hljs-builtin-name,
  #content_views .hljs-class .hljs-title,
  #content_views .hljs-meta {
    color: #ffa657 !important;
  }
  .hljs-operator,
  .hljs-punctuation,
  .hljs-params,
  #content_views .hljs-operator,
  #content_views .hljs-punctuation,
  #content_views .hljs-params {
    color: #c9d1d9 !important;
  }
  .hljs-tag,
  #content_views .hljs-tag {
    color: #7ee787 !important;
  }
  .hljs-emphasis { font-style: italic; }
  .hljs-strong { font-weight: bold; }

  /* ---- Prism.js syntax palette (`code.prism`) ----
     CSDN's CURRENT default renderer is Prism (span.token.*), not highlight.js —
     the .hljs-* map above never touches it. Our broad `span { color }` rule then
     flattened every Prism token to one body grey, so a modern CSDN code block
     shipped with NO syntax colours at all. `.token.x` is (0,2,0) so it beats the
     `span` rule without !important games. Same GitHub-dark palette as hljs. */
  .token.comment,
  .token.prolog,
  .token.doctype,
  .token.cdata {
    color: #8b949e !important;
    font-style: italic;
  }
  .token.keyword,
  .token.atrule,
  .token.important,
  .token.deleted {
    color: #ff7b72 !important;
  }
  /* `.token.regex-delimiter` / `-source` / `-flags` and `.token.template-string`
     are Prism's SPLIT token names (a regex literal and a template literal are
     tokenised into parts, not one `.regex` / `.string` span). They were absent
     from this palette, so our blanket `span { color !important }` — which beats
     Prism's own non-important `.token.x` rules — painted every regex literal and
     template string body grey: the two commonest string forms in JS code lost
     their syntax colour entirely. Same blue as `.string`. */
  .token.string,
  .token.char,
  .token.attr-value,
  .token.regex,
  .token.regex-delimiter,
  .token.regex-source,
  .token.regex-flags,
  .token.template-string,
  .token.inserted {
    color: #a5d6ff !important;
  }
  /* function parameters + the ${…} interpolation body inside a template string
     are plain code, not strings — keep them at the code base colour so they read
     as expressions rather than inheriting the blue above. */
  .token.parameter,
  .token.interpolation {
    color: #c9d1d9 !important;
  }
  .token.number,
  .token.boolean,
  .token.constant,
  .token.symbol {
    color: #79c0ff !important;
  }
  .token.function,
  .token.class-name {
    color: #d2a8ff !important;
  }
  .token.property,
  .token.attr-name,
  .token.variable {
    color: #79c0ff !important;
  }
  .token.builtin,
  .token.namespace {
    color: #ffa657 !important;
  }
  .token.tag,
  .token.selector {
    color: #7ee787 !important;
  }
  /* Prism's stock theme paints .token.operator/.entity/.url on a translucent
     WHITE background (hsla(0,0%,100%,.5)) — clear it, keep punctuation neutral */
  .token.operator,
  .token.punctuation,
  .token.entity,
  .token.url {
    color: #c9d1d9 !important;
    background: transparent !important;
  }
  .token.bold { font-weight: bold; }
  .token.italic { font-style: italic; }

  /* ---------- Markdown content extras ---------- */
  #content_views blockquote,
  .markdown_views blockquote {
    background-color: var(--csdn-elev) !important;
    border-left-color: var(--csdn-border) !important;
    color: var(--csdn-muted) !important;
  }
  #content_views table,
  .markdown_views table {
    border-color: var(--csdn-border) !important;
  }
  #content_views th,
  .markdown_views th {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text) !important;
    border-color: var(--csdn-border) !important;
  }
  #content_views td,
  .markdown_views td {
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  #content_views tr:nth-child(2n),
  .markdown_views tr:nth-child(2n) {
    background-color: var(--csdn-elev) !important;
  }
  #content_views hr {
    border-color: var(--csdn-border) !important;
    background-color: var(--csdn-border) !important;
  }

  /* ---------- Mermaid.js diagrams (```mermaid fenced blocks) ----------
     Mermaid renders flowcharts as inline SVG whose node shapes carry a light
     #ECECFF fill, whose edge labels sit on light rgb(232,232,232) pills, and
     whose connector lines/arrowheads are near-black #333 — all painted by
     Mermaid's own injected <style> as SVG `fill`/`stroke`, so the surface
     neutralizer never reached them: the boxes ship bright with washed-out grey
     labels and invisible connectors on the dark page. Darken the node fills,
     clear the label pills, and lighten the connectors + arrowheads. */
  .mermaid .node rect,
  .mermaid .node polygon,
  .mermaid .node circle,
  .mermaid .node ellipse,
  .mermaid .node path,
  .mermaid rect.basic,
  .mermaid .label-container,
  .mermaid .cluster rect {
    fill: var(--csdn-elev2) !important;
    stroke: var(--csdn-border) !important;
  }
  .mermaid .edgeLabel,
  .mermaid .edgeLabel foreignObject div,
  .mermaid span.edgeLabel,
  .mermaid .labelBkg {
    background-color: transparent !important;
    fill: transparent !important;
  }
  .mermaid .flowchart-link,
  .mermaid .edgePath path,
  .mermaid path.path {
    stroke: var(--csdn-muted) !important;
  }
  .mermaid .arrowMarkerPath,
  .mermaid marker path {
    fill: var(--csdn-muted) !important;
    stroke: var(--csdn-muted) !important;
  }

  /* ---------- Tags / chips ---------- */
  .tag-list a,
  .blog-tags-box a,
  .tags a,
  .label,
  .chip {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  /* article-footer tag pills (.tag-link-new — #java / #python / #算法) ship a
     pale-blue rgb(229,241,255) bg with blue link text = pale-on-pale on dark
     (audit-blind: ~49-66px wide pills under the big() threshold). Darken to an
     elevated surface, keep the blue tag-link text. */
  .tag-link-new,
  .article-footer-pill-list a {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
    border-color: var(--csdn-border) !important;
  }
  /* article aside "TA的精选" recommend-list badges (span.tag in .his-selection-box):
     新 ships a solid brand-red rgb(252,85,49) pill and 热 a pale-pink rgb(255,238,234)
     pill — both 19×17, under the audit big() floor. Our muted `.tag` rule greyed both
     labels (grey-on-red for 新, and grey-on-pale-pink for 热 — the latter a bright
     washed-out spot on dark). Keep 新's red pill with a white label; darken 热's pill to
     a red tint with brand-red text. The (0,2,1)/(0,3,1) selectors beat the `.tag` rule. */
  .his-selection-box span.tag {
    color: #ffffff !important;
  }
  .his-selection-box span.tag.active {
    background-color: rgba(240, 121, 92, 0.16) !important;
    color: var(--csdn-red) !important;
  }
  /* author-card "博客等级" blog-level badge (.profile-intro-name-leve) ships a
     light-grey rgb(245,246,247) pill; our lightened text then goes light-on-
     light (audit-blind: 84×21 pill). Darken it. */
  .profile-intro-name-leve {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }
  /* member/course-card "VIP" pill (p.tag) is a GOLD gradient background-IMAGE
     with dark-brown label text. The bg-image survives our neutralizer, but the
     muted-metadata `.tag` rule repainted the label light grey — grey-on-gold,
     ~1.9:1. Restore the site's brown so the gold pill stays legible. */
  .member-item p.tag,
  a > div.image > p.tag {
    color: #69421b !important;
  }
  /* headline-list bullets (span.border) are literal 8px #ccc squares — a subtle
     marker on the native white page, the brightest pixels on ours */
  .home-info-headlines a span.border {
    background-color: #30363d !important;
  }
  /* article "AI阅读助手" side-slide widget (.cknows-side) feature chips
     (提炼文本 / 高效总结 / 30秒速读) ship a light rgb(242,242,242) pill, 63×24 —
     under the audit big() floor, so light-on-light once our theme lifts the
     label. Darken to an elevated surface. */
  .cknows-side-tag,
  .cknows-side-tags span {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  /* article aside "分类专栏" list: the "付费" paid marker is a brand-red rgb(252,85,49)
     label with a matching red border — the blanket text rule greyed the label and
     `* { border-color }` greyed the border, erasing the paid-content signal. On the
     user profile / blog-home the same marker ships as a `div.pay-tag` (the article
     aside variant is a `span`), so cover both tags. Restore a dark-tuned brand red. */
  span.pay-tag,
  div.pay-tag {
    color: var(--csdn-red) !important;
    border-color: var(--csdn-red) !important;
  }

  /* ---------- Search-results filters / sort tabs (all states) ---------- */
  .so-search,
  .so-result,
  .search-list-con,
  .so-sort,
  .sort,
  .common-lt,
  .so-tab,
  .toolbar-tab,
  .tab-list,
  .search-input-box {
    background-color: transparent !important;
    color: var(--csdn-text-2) !important;
  }
  .sort .item,
  .common-lt span,
  .so-sort .item,
  .tab-list .tab {
    color: var(--csdn-muted) !important;
  }
  .sort .active,
  .common-lt .active,
  .so-sort .item.active,
  .tab-list .tab.active,
  .so-tab .active {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
  }
  /* so.csdn.net "筛选" filter panel (时间 / 类型 / 领域 rows, revealed by the 筛选
     toggle — closed at load, so no load-time scan sees it): the site marks the
     SELECTED value with brand orange rgb(254,107,0) and greys the rest (#555666).
     Our blanket `span` rule painted every value the same body grey, erasing the
     selection: all six time chips read identically. Restore the accent on the
     selected chip and keep the others muted. */
  .filters .filter .f-bd span {
    color: var(--csdn-muted) !important;
  }
  .filters .filter .f-bd span.active {
    color: #fe6b00 !important;
  }

  /* so.csdn.net "相关搜索" related-term chips: the first (hot) chip is a
     classless .so-hot-words li with a hardcoded white bg (92×28 — below the
     audit height threshold, so audit-blind) carrying pale-blue link text
     that washes out on white. Darken every chip uniformly to an elevated
     surface so the blue term text reads. */
  .so-hot-words ul li,
  .so-hot-words .hw-bd li {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  /* so.csdn.net "搜索发现" rank ordinals: the site colours the top three
     (#fe2d46 / #f60 / #faa90e) and greys the rest — our muted `.num` rule
     flattened all of them. Restore, lifting only #1 (#fe2d46 is 4.07:1 on the
     dark base) to a readable red. The widget renders as .wrap-hot on the live
     results page; .related-list is the same list on the sidebar variant. */
  .wrap-hot ul li:first-child .num,
  .related-list ul li:first-child .num {
    color: #ff5a6e !important;
  }
  .wrap-hot ul li:nth-child(2) .num,
  .related-list ul li:nth-child(2) .num {
    color: #f60 !important;
  }
  .wrap-hot ul li:nth-child(3) .num,
  .related-list ul li:nth-child(3) .num {
    color: #faa90e !important;
  }

  /* search submit button — brand red, white glyph */
  #toolbar-search-button,
  .so-search-btn,
  .search-btn {
    background-color: #d6492b !important;
    color: #ffffff !important;
    border-color: #d6492b !important;
  }

  /* VIP / 会员 gold badge — keep brand gold, dark legible text */
  .vip-tag,
  .vip-flag,
  .member-tag,
  .icon-vip {
    color: #1a1d21 !important;
  }

  /* Secondary outline buttons (私信 / 关注专栏 etc.) — dark surface, blue label */
  .bt-button,
  a.bt-button,
  .personal-letter,
  .article-column-bt,
  .articleColumnFreeB,
  .tool-attend.tool-bt-button,
  .item-target.article-column-bt {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
    border-color: var(--csdn-border) !important;
  }

  /* ---------- Brand accent (CSDN red) — refined for dark ----------
     CSDN's primary CTAs use a saturated #fc5531 red. Keep the brand
     identity but settle it onto the dark palette and keep label text
     bright white for a readable, intentional CTA. */
  .csdn-toolbar-loginbtn,
  a.csdn-toolbar-loginbtn,
  .csdn-toolbar-regbtn,
  .toolbar-btn-reg,
  .toolbar-btn-write,
  .toolbar-btn-write-new,
  .personal-watch,
  a.personal-watch,
  a.personal-watch.bt-button,
  .bt-button.personal-watch,
  .tool-attend.tool-bt-atten,
  a.tool-bt-atten,
  .btn-red,
  .btn-follow,
  .follow-btn,
  .attention-box .attention,
  .login-box .btn,
  button.runner-btn {
    background-color: #d6492b !important;
    color: #ffffff !important;
    border-color: #d6492b !important;
  }
  /* keep any nested label/icon inside a brand-red CTA white */
  .csdn-toolbar-loginbtn *,
  .csdn-toolbar-regbtn *,
  .toolbar-btn-write *,
  .personal-watch *,
  button.runner-btn * {
    color: #ffffff !important;
  }

  /* ---------- White gradient fades (expand-all / read-more masks) ----------
     CSDN paints a white→transparent linear-gradient over the bottom of the
     category-column list ("展开全部"), collapsed article bodies ("阅读全文")
     and similar widgets. The fade is a background-IMAGE (the bg-color
     neutralizer leaves it untouched), so remap each fade to fall toward the
     dark page base instead of bright white. */
  .flexible-btn-new,
  .hide-article-box,
  .hide-article-pos,
  .hide-preCode-box,
  .readall_box,
  .tool-active-list .read-all {
    background-image: linear-gradient(rgba(20, 24, 29, 0), var(--csdn-base) 62%) !important;
  }
  .flexible-btn-new {
    color: var(--csdn-link) !important;
  }
  /* home category chip carousel edge fades: the horizontal-scroll nav
     (.menus-view_prev / _next) paints a white→transparent linear-gradient
     mask over the left/right chips to hint "more categories" (a background-
     IMAGE, so the bg-color audit misses it, and each mask is <52px wide so
     the big() height/width filter skips it too). Remap the white stop to the
     dark page base so the fade blends into the chip row. */
  .menus-view_next {
    background-image: linear-gradient(90deg, rgba(20, 24, 29, 0), var(--csdn-base) 52px) !important;
  }
  .menus-view_prev {
    background-image: linear-gradient(270deg, rgba(20, 24, 29, 0), var(--csdn-base) 32px) !important;
  }
  /* code-block header InsCode runner-button strip: a .mask child paints a
     horizontal white→transparent fade (background-IMAGE, audit-blind) at the
     strip edge — drop it so the dark code header stays clean */
  .ins-code-runner-btn .mask,
  div.ins-code-runner-btn > .mask {
    background-image: none !important;
  }

  /* ---------- AtomGit / GitCode "quick-app" promo card (article sidebar) ----------
     A large promo tile whose .gitcode-work-space carries a near-white
     background-IMAGE gradient (invisible to the bg-color audit). Flatten it
     to a dark elevated surface and lighten its light-on-white copy. */
  body div.gitcode-quick-app,
  body div.gitcode-quick-app.light,
  body div.gitcode-qc-left-box,
  body div.gitcode-work-space {
    background-color: var(--csdn-elev) !important;
    background-image: none !important;
    border-color: var(--csdn-border) !important;
  }
  body div.gitcode-quick-app,
  body div.gitcode-quick-app * {
    color: var(--csdn-text-2) !important;
  }
  /* the promo's header banner is a raster PNG with a baked-in light
     background — drop it so its caption sits on the dark card */
  body div.gitcode-quick-app .csdn-card-content {
    background-image: none !important;
  }

  /* ---------- AI search card ("开发者首选的 AI 搜索引擎") ----------
     The AI-search promo wraps its dark textarea in a .chat-input-main box
     painted white via a background-IMAGE gradient (bg-color transparent, so
     audit-blind). Flatten it to a dark elevated surface so only the textarea
     + brand-purple submit button read on it. On the so.csdn.net results page
     this card now renders inside an ai.csdn.net/chat IFRAME, where
     .chat-input-main has NO .ai-search-card ancestor (that wrapper lives in
     the parent document) — so match .chat-input-main standalone too, else the
     iframe card ships bright white. */
  body div.ai-search-card,
  body .ai-search-card .chat-input-main,
  .chat-input-main {
    background-color: var(--csdn-elev) !important;
    background-image: none !important;
    border-color: var(--csdn-border) !important;
  }

  /* tiny white ::before slivers on article/profile asides — neutralize them */
  #aside-content::before,
  #aside-content::after,
  .aside-common-box-content.aside-box-fold::before,
  .aside-common-box-content.aside-box-fold::after {
    background-color: transparent !important;
  }

  /* ---------- Blog-article "skin" raster bars ----------
     When an author applies a CSDN skin (skin-1024 etc.), the article aside
     section headers (.aside-title — 最新评论/大家在看/最新文章/上下篇) and the
     comment-form title (.title-box) render a light bg-nav.png / comment-title
     raster as a background-IMAGE. The bg-color audit misses url() images, so
     these ship as bright white bars. Drop the raster, keep the title text. */
  h3.aside-title,
  .aside-title,
  .comment-box .title-box,
  div.title-box {
    background-image: none !important;
    background-color: transparent !important;
    color: var(--csdn-text) !important;
  }

  /* aside "最新评论" comment previews use solid-white ::before (the "..."
     ellipsis indicator) + ::after (fade mask) pseudo-elements (bg-color
     audit-blind) — they paint a bright "..." sliver bottom-right on dark.
     Remap both to the page base so they blend invisibly. */
  .aside-content .newcomment-list li p.comment::before,
  .aside-content .newcomment-list li p.comment::after,
  .newcomment-list li p.comment.ellipsis::before,
  .newcomment-list li p.comment.ellipsis::after {
    background-color: var(--csdn-base) !important;
    background-image: none !important;
    color: var(--csdn-muted) !important;
  }

  /* ---------- 问答 (ask.csdn.net) ----------
     The Q&A subdomain ships a light active channel pill, a white
     leaderboard header, and a selected filter tag whose dark text
     (driven by -webkit-text-fill-color) goes dark-on-dark. */
  /* every channel-list row turns a light rgb(245,246,247) on :hover (audit-blind:
     the light bg only exists while hovered, and each row is 160×32, under the big()
     floor). Left the hovered row a bright light-grey box with pale text on dark.
     Recolor the hover state to a dark tint; declared BEFORE .cur/.active (equal
     specificity) so the selected row keeps its brighter active surface while hovered. */
  .channelList li:hover {
    background-color: var(--csdn-elev) !important;
  }
  .channelList li.cur,
  .channelList li.active {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text) !important;
  }
  .tag_name_item.currentTagName,
  .tag_list_box .currentTagName {
    color: var(--csdn-link) !important;
    -webkit-text-fill-color: var(--csdn-link) !important;
  }
  .ask-urgent-list h4 {
    background-color: var(--csdn-elev) !important;
    color: var(--csdn-text) !important;
  }
  /* 采纳榜 leaderboard podium: the site colour-codes the top three ordinals through
     dedicated classes (.ic_rank_1 red / _2 gold / _3 rose) and greys 4+ — the
     blanket span text rule collapsed all ten to the same grey, so the podium read
     exactly like the rest of the list. Restore the three, lifted for the dark base. */
  span.rank.ic_rank_1 {
    color: #ff6b52 !important;
  }
  span.rank.ic_rank_2 {
    color: #f7c72d !important;
  }
  span.rank.ic_rank_3 {
    color: #cb9696 !important;
  }

  /* ---------- User profile page "skin" background ----------
     Profile pages render a user-chosen "skin" as a full-page light
     background-IMAGE on .skin3-template (e.g. user-skin-White) plus a
     light .user-profile-head cover banner. With our transparent content
     containers the light image shows through behind light text and makes
     the whole profile unreadable — strip the skin image, paint dark. */
  .skin3-template,
  .skin-number,
  [class*="user-skin"],
  .user-profile-head {
    background-image: none !important;
    background-color: var(--csdn-base) !important;
  }
  /* profile content tab strip (.navList): the site signals the ACTIVE tab only
     by darkness (#222226 active vs #555666 inactive), so once our theme lifted
     every li to the same body grey the selected tab became indistinguishable.
     Re-establish the contrast, inverted for dark. */
  .navList ul li {
    color: var(--csdn-muted) !important;
  }
  .navList ul li.active {
    color: var(--csdn-text) !important;
  }

  /* the "原力等级" achievement / influence card (active state is white) */
  .user-influence-list,
  .user-influence-list.active,
  .aside-common-box-achievement li {
    background-color: var(--csdn-elev) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }

  /* ---------- passport.csdn.net login / register page ----------
     The login page paints a full-viewport decorative isometric-city
     illustration as a background-IMAGE on .passport-container (bg-color
     transparent, so audit-blind), and the .login-box / .passport-main card
     is flattened to transparent by the broad neutralizer — the login form
     (titles, tab labels, "扫码登录" copy) then floats unreadably over the
     busy light illustration. Drop the raster and re-seat the card as a
     solid dark elevated surface. Higher specificity (body div.…) so it
     wins over the equal-specificity neutralizer by source order. */
  .passport-container {
    background-image: none !important;
    background-color: var(--csdn-base) !important;
  }
  body div.passport-main,
  body div.login-box,
  body div.passport-box,
  body div.login-content,
  body div.login-form {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }
  .login-box .title,
  .passport-main .title {
    color: var(--csdn-text) !important;
  }
  /* "上次登录/扫码登录更方便" last-login hint pill above the login tabs ships a
     warm cream rgb(254,247,240) bg with pale text — light-on-light (audit-blind:
     120×22 pill under the big() threshold). Repaint dark + its down-arrow pseudo. */
  .last-login-way {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
  }
  .last-login-way::before,
  .last-login-way::after {
    background-color: var(--csdn-elev2) !important;
    border-top-color: var(--csdn-elev2) !important;
  }
  /* login-method tabs (微信登录 / 验证码登录 / APP登录): the selected tab is marked
     ONLY by a near-black #222226 label plus a #222226 ::after underline. On the
     dark card the underline is invisible and every tab reads the same, so the
     form gives no sign of which login method is active. */
  .login-box-tabs-items span {
    color: var(--csdn-muted) !important;
  }
  .login-box-tabs-items span.tabs-active {
    color: var(--csdn-text) !important;
  }
  /* the "上次登录" hint pill is a sibling span in the same row — restore it after
     the muted rule above rather than excluding it with a :not() */
  .login-box-tabs-items span.last-login-way {
    color: var(--csdn-text-2) !important;
  }
  .login-box-tabs-items span.tabs-active::after {
    background-color: #fc5531 !important;
  }

  /* ---------- Element UI cards (download.csdn.net / 文库 + Vue pages) ----------
     The 文库/download frontend is built on Element UI; its .el-card panels
     (e.g. the "资源创作成就榜" leaderboard) ship a hardcoded white surface. */
  .el-card,
  .el-card__body,
  .el-card__header,
  .el-card.is-never-shadow,
  .el-tabs__content,
  .el-collapse-item__content {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }
  .el-card__body ul > li,
  .el-card__body > ul > li {
    background-color: transparent !important;
    color: var(--csdn-text-2) !important;
  }
  /* Element UI toasts (.el-message) and confirm dialogs (.el-message-box) are
     floating div[class] surfaces, so the broad neutralizer strips their light
     background and the page bleeds through the toast. They are transient — a
     chroma scan caught one mid-flight — so no load-time screenshot shows them.
     Re-seat them opaque, and keep the error/success/warning type colours that
     the blanket text rules would otherwise collapse into one grey. */
  body div.el-message,
  body div.el-message-box,
  body div.el-message-box__header,
  body div.el-message-box__content {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
  }
  .el-message__content {
    color: var(--csdn-text-2) !important;
  }
  .el-message--error .el-message__content {
    color: var(--csdn-red) !important;
  }
  .el-message--success .el-message__content {
    color: #7ee787 !important;
  }
  .el-message--warning .el-message__content {
    color: #e3a75f !important;
  }

  /* Element UI checkbox (so.csdn.net "VIP内容" result filter, download forms)
     ships a literal white 14px box — too small for the audit size filter.
     Only repaint the UNCHECKED box so the checked brand-blue fill survives. */
  .el-checkbox__input:not(.is-checked) .el-checkbox__inner,
  .el-radio__input:not(.is-checked) .el-radio__inner {
    background-color: var(--csdn-elev2) !important;
    border-color: var(--csdn-border) !important;
  }

  /* download.csdn.net sidebar panels paint a light PNG as a background-IMAGE
     behind real DOM copy (bg-color audit-blind): the 会员 promo header
     (.user-info > .top-info) and the 创作灵感 / upload panel
     (.upload-sidebar). Our lifted text ships white-on-white on both. */
  body div.user-info > div.top-info,
  body div.upload-sidebar {
    background-image: none !important;
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
  }
  /* resource-card category chips (.header-tag) + the el-card header pill ship
     a pale rgb(247,247,252) bg under pale-blue link text = pale-on-pale */
  .resource-card .header-tag,
  a.header-tag,
  .el-card__header button.header-info {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
    border-color: var(--csdn-border) !important;
  }
  /* download.csdn.net paints price, "免费"/membership markers and the 查看 /
     去上传 affordances in brand red #fc5531 — the blanket div/span text rules
     collapsed every one of them to body grey. 查看 and 免费 additionally sit on a
     rgba(252,85,49,.1) red-tinted chip, so grey text there is a genuine
     mismatch. Restore a dark-tuned brand red. */
  body div.price,
  body span.price,
  .price em,
  span.free,
  span.view-btn,
  span.to-upload {
    color: var(--csdn-red) !important;
  }
  /* download.csdn.net resource-rank list (.latest-file-card): the site colour-codes
     the top three ordinals (#1 coral, #2 gold, #3 bronze) and greys the rest — the
     blanket div/span text rules collapsed all of them to one body grey, erasing the
     podium. Rows past the first are collapsed (li.fold) for guests, so no load-time
     scan or screenshot reaches them; restore the three medal colours. */
  .latest-file-card ul li:nth-child(1) .rank,
  .latest-file-card ul li:nth-child(1) .rank span {
    color: #f87e62 !important;
  }
  .latest-file-card ul li:nth-child(2) .rank,
  .latest-file-card ul li:nth-child(2) .rank span {
    color: #fab216 !important;
  }
  .latest-file-card ul li:nth-child(3) .rank,
  .latest-file-card ul li:nth-child(3) .rank span {
    color: #d29223 !important;
  }
  /* download.csdn.net "资源创作成就榜" leaderboard (.el-card, visible at load): a
     SECOND podium the .latest-file-card rules never reach — the site colours the
     top three .rankNum ordinals (#1 coral #fc5531 / #2 gold / #3 rose) and greys 4+
     (#555666). The blanket div text rule collapsed all of them to one body grey, so
     ranks 1-5 read identically. The ordinal is a bare <div class="rankNum"> keyed by
     li:nth-child (no per-row class), so restore the three medal colours by position. */
  .el-card__body ul li:nth-child(1) .rankNum {
    color: #ff6b52 !important;
  }
  .el-card__body ul li:nth-child(2) .rankNum {
    color: #f7c72d !important;
  }
  .el-card__body ul li:nth-child(3) .rankNum {
    color: #cb9696 !important;
  }
  /* the gold "开通会员" pill is a raster background-IMAGE, so its brown label
     must stay brown — our grey washed it out on the gold */
  a.vip-button span.preferential {
    color: #925417 !important;
  }
  /* the active toolbar tab is marked ONLY by a 2px #fc5531 top border, which the
     blanket `* { border-color }` rule flattened into the ordinary line colour */
  a.custom_toolbar_content_active {
    border-color: #fc5531 !important;
  }

  /* download.csdn.net "新版内容上线啦" onboarding modal: .right-content paints
     a white raster panel (bg-IMAGE, audit-blind) and all the title/feature
     text is real DOM that our theme lightens — light-on-white = unreadable.
     Flatten the panel to a dark surface so the light copy + colored feature
     icons read; brand the CTA. */
  .dialog-tip,
  .dialog-tip .right-content,
  .dialog-tip .left-content {
    background-image: none !important;
    background-color: var(--csdn-elev) !important;
  }
  .dialog-tip .title {
    color: var(--csdn-text) !important;
  }
  .dialog-tip .text {
    color: var(--csdn-text-2) !important;
  }
  /* the modal's "体验新功能" CTA is a <div class="btn"> with a #fc5531 fill — the
     broad neutralizer stripped the fill and our .btn rule greyed the label, so
     the only action in the dialog rendered as plain body text */
  body div.dialog-tip div.btn {
    background-color: #d6492b !important;
    color: #ffffff !important;
    border-color: #d6492b !important;
  }
  /* the left panel is a decorative cube-animation <video> with a baked-in
     light background — hide it so the flattened dark left panel stays clean */
  .dialog-tip .left-content video {
    display: none !important;
  }

  /* ---------- Download-recommend feed (blog list / 404 / column pages) ----------
     The .feed.floatR recommend list renders each row (li.pub_recom_item)
     on a hardcoded white surface with faint grey titles — darken the rows
     and lift the text. */
  .pub_recom_item,
  .pub_recom_item.download,
  .pub_recommend > li {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }
  .pub_recom_item .tit,
  .pub_recom_item h3,
  .pub_recom_item a,
  .pub_recom_item .desc {
    color: var(--csdn-text-2) !important;
  }

  /* edu.csdn.net lecturer-card light divider borders */
  #lecturer-sug .lecturer-sug-bottom span.border {
    border-color: var(--csdn-border) !important;
  }
  /* edu.csdn.net toolbar dropdown toggles — dark text (via fill) on dark chrome */
  .edu-toolbar .edu-submenu-dropdown-toggle,
  .edu-toolbar-item button {
    color: var(--csdn-text) !important;
    -webkit-text-fill-color: var(--csdn-text) !important;
  }

  /* bbs.csdn.net community-switcher (.compont-title: 社区推荐 / 我的社区 / Ada助手):
     the site marks the ACTIVE tab only by a 2px bottom underline (all three share the
     same text colour), which our `* { border-color }` reset flattened to the invisible
     line colour — so the selected tab became indistinguishable. Restore a brand-red
     underline on the active tab. */
  .compont-title h3.active {
    border-bottom-color: #fc5531 !important;
  }

  /* bbs.csdn.net (社区) banner quick-link cards — white with light text */
  .bbs-banner_links li {
    background-color: var(--csdn-elev) !important;
    background-image: none !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text-2) !important;
  }
  /* bbs community-recommend rail "加入" buttons ship a literal white 48×24
     pill (a <button>, so the div/section neutralizer misses it, and it is
     under the audit big() threshold). */
  .bbs-recommend-list_ul li button,
  .bbs-recommend-list_ul button {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-link) !important;
    border-color: var(--csdn-border) !important;
  }
  /* bbs feed red-packet greeting pill: pale-pink rgb(253,231,232) bg whose
     label our muted grey then renders light-on-light. Tint it dark, keep the
     red-packet brand red on the label. */
  .red-packet-icon-mini .num,
  span.red-packet-icon-mini > span.num {
    background-color: #3d2124 !important;
    color: var(--csdn-red) !important;
  }

  /* ---------- 问答 (ask.csdn.net) question-card meta pills ----------
     The .slug-nav row under each question renders its tag pill on a pale
     rgb(235,242,247) and its view-count / timestamp pills on literal white
     (20px tall, so under the audit big() floor). Our lightened labels then
     go light-on-light. Darken the whole row. */
  .question-header .slug-nav li,
  .slug-nav li.other-data,
  .slug-nav li.other-data.views {
    background-color: var(--csdn-elev2) !important;
    color: var(--csdn-text-2) !important;
    border-color: var(--csdn-border) !important;
  }
  /* the 采纳榜 leaderboard's selected range chip paints a mid-grey
     rgb(193,193,193) box under our light label */
  .diff-camp .active-camp span,
  .diff-camp span.camp.active-camp > span {
    background-color: #30363d !important;
    color: var(--csdn-text) !important;
  }
  /* white sliver behind the collapsed channel-list button row */
  .channelList li.btns_li {
    background-color: transparent !important;
  }

  /* ---------- Images / avatars keep their own pixels ---------- */
  img,
  .avatar,
  .user-avatar {
    background-color: transparent !important;
  }

  /* ---------- Home left-sidebar nav icons ----------
     The www.csdn.net left sidebar (.layout-menus) renders each nav
     glyph as a monochrome near-BLACK raster <img> (首页/博客/下载/学习/
     社区 + 订阅/关注/收藏/历史/会员中心/创作中心/我的算力). On the dark
     sidebar these are dark-on-dark and nearly invisible. They carry no
     class/attr to target, so we recolor by their stable CDN filenames:
     invert the black pixels to a readable muted light. The COLORED brand
     icons (模型市场/AI搜索/AtomGit/InsCode/技术会议) are NOT in this list,
     so they keep their original colors. */
  .layout-menus .layout-menu-item_icon img[src*="20241216111623"],
  .layout-menus .layout-menu-item_icon img[src*="20241216111636"],
  .layout-menus .layout-menu-item_icon img[src*="20241216111629"],
  .layout-menus .layout-menu-item_icon img[src*="20250113040415"],
  .layout-menus .layout-menu-item_icon img[src*="20241216111644"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025916"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025921"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025925"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025927"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025930"],
  .layout-menus .layout-menu-item_icon img[src*="20241216025933"],
  .layout-menus .layout-menu-item_icon img[src*="b218ee9788964cb681ba51bf5089b2dc"] {
    filter: invert(1) brightness(0.85) !important;
  }
  /* active item glyph stays a touch brighter */
  .layout-menus .layout-menu-item.active .layout-menu-item_icon img[src*="20241216111623"] {
    filter: invert(1) brightness(1) !important;
  }

  /* ---------- Google Funding Choices consent sheet ----------
     CSDN serves the IAB-TCF CMP (.fc-consent-root) to EU visitors on first
     visit; its stylesheet is injected AFTER our theme, so a bare .fc-dialog
     rule ties on specificity and loses on source order. Scope every rule from
     .fc-consent-root to out-specify it and dark the whole white sheet. */
  .fc-consent-root .fc-dialog,
  .fc-consent-root .fc-dialog-content,
  .fc-consent-root .fc-choice-dialog,
  .fc-consent-root .fc-header,
  .fc-consent-root .fc-footer {
    background-color: var(--csdn-elev) !important;
    color: var(--csdn-text) !important;
    border-color: var(--csdn-border) !important;
  }
  .fc-consent-root .fc-dialog h1,
  .fc-consent-root .fc-dialog h2,
  .fc-consent-root .fc-dialog p,
  .fc-consent-root .fc-dialog li,
  .fc-consent-root .fc-dialog span,
  .fc-consent-root .fc-dialog div,
  .fc-consent-root .fc-dialog-headline,
  .fc-consent-root .fc-dialog-content {
    color: var(--csdn-text) !important;
    -webkit-text-fill-color: var(--csdn-text) !important;
  }
  .fc-consent-root .fc-faq-icon,
  .fc-consent-root .fc-faq-contents {
    background-color: var(--csdn-base) !important;
  }
  /* the "Learn more" expander disc: Funding Choices paints it white through
     `.fc-consent-root .fc-faq-header .fc-faq-icon` (0,3,0) !important, which
     out-specifies the (0,2,0) rule above — so a bright 28px white circle
     survived on the dark sheet. Match their specificity, and lift the chevron
     (a #5f6368 SVG drawn for a white disc) so it stays visible on the dark one. */
  .fc-consent-root .fc-faq-header .fc-faq-icon {
    background-color: var(--csdn-elev2) !important;
    border-color: var(--csdn-border) !important;
  }
  .fc-consent-root .fc-faq-header .fc-faq-icon svg,
  .fc-consent-root .fc-faq-header .fc-faq-icon svg path {
    fill: var(--csdn-text-2) !important;
  }
  .fc-consent-root .fc-dialog hr {
    background-color: var(--csdn-border) !important;
    border-color: var(--csdn-border) !important;
  }
  /* "Manage options" preferences panel: sticky header, each purpose card and
     the vendor rows all ship a literal white surface */
  .fc-consent-root .fc-dialog-header,
  .fc-consent-root .fc-navigation-button,
  .fc-consent-root .fc-manage-vendors {
    background-color: var(--csdn-elev) !important;
    border-color: var(--csdn-border) !important;
  }
  .fc-consent-root .fc-preference-container {
    background-color: var(--csdn-elev2) !important;
    border-color: var(--csdn-border) !important;
  }
  /* the "TCF vendors" section divider is a rgb(241,243,244) bar the rule above
     never named, and the "Manage vendors" footer button is repainted white by
     `.fc-consent-root .fc-data-preferences-dialog .fc-navigation-button` (0,3,0),
     which out-specifies our (0,2,0) rule — both shipped as bright bars carrying
     our lifted (near-white) label text. Match/beat their specificity. */
  .fc-consent-root div.fc-preference-divider,
  .fc-consent-root .fc-data-preferences-dialog .fc-navigation-button,
  .fc-consent-root .fc-data-preferences-dialog .fc-manage-vendors {
    background-color: var(--csdn-elev2) !important;
    border-color: var(--csdn-border) !important;
    color: var(--csdn-text) !important;
  }
  .fc-consent-root div.fc-preference-divider p,
  .fc-consent-root .fc-data-preferences-dialog .fc-navigation-button span {
    color: var(--csdn-text) !important;
    -webkit-text-fill-color: var(--csdn-text) !important;
  }

  /* ---------- Scrollbar ---------- */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: var(--csdn-base); }
  ::-webkit-scrollbar-thumb {
    background: #30363d;
    border-radius: 6px;
    border: 3px solid var(--csdn-base);
  }
  ::-webkit-scrollbar-thumb:hover { background: #3d444d; }

  /* ---------- Selection ---------- */
  ::selection {
    background: #2d5986;
    color: #fff;
  }
}
